    for Lr in [srow-1.5,srow-0.5,srow,srow+0.5,srow+1.5]:
        for Lv in [scol-1.5,scol-0.5,scol,scol+0.5,scol+1.5]:
            pred=np.array(f(i,Lr,Lv))
            if np.array_equal(pred,o):
                print('pair',n,'MATCH Lr,Lv=',Lr,Lv); found=True; break
        if found: break
    print('pair',n,'any match:',found)

